import type { Request, Response, Express } from "express";
import { z } from "zod";
import { storage } from "../../storage.js";

const insertResetPasswordSchema = z.object({
  token: z.string(),
  new_password: z.string(),
});

export function registerPostApiAuthResetPasswordRoutes(app: Express): void {
  app.post("/api/auth/reset-password", async (req: Request, res: Response) => {
    try {
      const parsed = insertResetPasswordSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: parsed.error.issues[0].message });
      const created = await storage.createResetPassword(parsed.data);
      res.status(201).json(created);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });
}
